package com.englishhero.practice;

import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.*;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticeSubjectiveDtos.*;

@Service
@Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticeSubjectiveService {
 private final org.springframework.jdbc.core.JdbcTemplate jdbc;private final PracticeSetMapper sets;private final PracticeAttemptMapper users;private final PracticeSubjectiveAdminService contents;private final IdentityService identities;private final PracticePublicationChecks hashes;private final ObjectMapper json;
 public PracticeSubjectiveService(PracticeSetMapper sets,PracticeAttemptMapper users,PracticeSubjectiveAdminService contents,IdentityService identities,PracticePublicationChecks hashes,ObjectMapper json,org.springframework.jdbc.core.JdbcTemplate jdbc){this.jdbc=jdbc;this.sets=sets;this.users=users;this.contents=contents;this.identities=identities;this.hashes=hashes;this.json=json;}
 record Row(long id,long user,long set,long setVersion,Long parent,String text,int words,String status,int version,Instant started,Instant updated,Instant completed){}
 private final RowMapper<Row> rows=(r,n)->new Row(r.getLong("id"),r.getLong("user_id"),r.getLong("set_id"),r.getLong("set_version_id"),r.getObject("parent_attempt_id",Long.class),r.getString("answer_text"),r.getInt("word_count"),r.getString("status"),r.getInt("lock_version"),r.getTimestamp("started_at").toInstant(),r.getTimestamp("updated_at").toInstant(),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toInstant());
 private Row owned(long user,String id,boolean lock){return jdbc.query("SELECT * FROM practice_subjective_attempt WHERE user_id=? AND id=?"+(lock?" FOR UPDATE":""),rows,user,ArticleRules.id(id,"attemptId")).stream().findFirst().orElseThrow(PracticeAdminService::missing);}
 private Row active(long user,long set){return jdbc.query("SELECT * FROM practice_subjective_attempt WHERE user_id=? AND set_id=? AND status='IN_PROGRESS' FOR UPDATE",rows,user,set).stream().findFirst().orElse(null);}
 private void version(Row r,Integer version){if(!r.status().equals("IN_PROGRESS")||version==null||version!=r.version())throw conflict();}
 private static BusinessException conflict(){return new BusinessException(409,"PRACTICE_CONFLICT","练习已在其他页面更新，请保留当前文字并重新加载");}
 private Long replay(long user,String request,String operation,Object input){PracticeAttemptService.requestId(request);String hash=hashes.hash(input);var old=jdbc.queryForList("SELECT operation,request_hash,attempt_id FROM practice_subjective_request WHERE user_id=? AND request_id=?",user,request);if(old.isEmpty())return null;var row=old.getFirst();if(!operation.equals(row.get("operation"))||!hash.equals(row.get("request_hash")))throw conflict();return ((Number)row.get("attempt_id")).longValue();}
 private void remember(long user,String request,String op,Object input,long attempt){jdbc.update("INSERT INTO practice_subjective_request(user_id,request_id,operation,request_hash,attempt_id) VALUES(?,?,?,?,?)",user,request,op,hashes.hash(input),attempt);}
 private Attempt dto(Row r){var v=sets.version(r.setVersion());var m=json.readValue(v.metadata(),PracticeDtos.Metadata.class);var c=contents.content(v.id(),true);boolean done=r.status().equals("COMPLETED");return new Attempt(""+r.id(),""+r.set(),""+r.setVersion(),r.parent()==null?null:""+r.parent(),m.titleZh().isBlank()?m.title():m.titleZh(),v.readingType(),c.publicPrompt(),r.text(),r.words(),r.status(),r.version(),r.started(),r.updated(),r.completed(),done?c.reference():null,done?c.notes():null);}
 public Attempt get(SessionPrincipal actor,String id){identities.current(actor);return dto(owned(actor.userId(),id,false));}
 public Attempt start(SessionPrincipal actor,String id,PracticeDtos.StartInput input){identities.current(actor);if(input==null)throw BusinessException.invalid("requestId","请提供开始命令");long sid=ArticleRules.id(id,"setId");long vid=ArticleRules.id(input.setVersionId(),"setVersionId");users.lockUser(actor.userId());var command=List.of(id,input);Long old=replay(actor.userId(),input.requestId(),"START",command);if(old!=null)return dto(owned(actor.userId(),""+old,false));var set=sets.get(sid,true);if(set==null||!"PUBLISHED".equals(set.status())||!PracticeSubjectiveRules.isSubjective(set.readingType()))throw PracticeAdminService.missing();if(!Objects.equals(set.publishedVersionId(),vid))throw conflict();var active=active(actor.userId(),sid);long created;if(active!=null)created=active.id();else created=create(actor.userId(),sid,vid,null,"");remember(actor.userId(),input.requestId(),"START",command,created);return dto(owned(actor.userId(),""+created,false));}
 private long create(long user,long set,long version,Long parent,String text){return sets.insert("INSERT INTO practice_subjective_attempt(user_id,set_id,set_version_id,parent_attempt_id,answer_text,word_count) VALUES(?,?,?,?,?,?)",user,set,version,parent,text,PracticeSubjectiveRules.words(text));}
 public Attempt save(SessionPrincipal actor,String id,DraftInput input){identities.current(actor);if(input==null)throw BusinessException.invalid("answerText","请提供草稿");String text=PracticeSubjectiveRules.answer(input.answerText());var r=owned(actor.userId(),id,true);version(r,input.expectedVersion());jdbc.update("UPDATE practice_subjective_attempt SET answer_text=?,word_count=?,lock_version=lock_version+1,updated_at=UTC_TIMESTAMP(6) WHERE id=?",text,PracticeSubjectiveRules.words(text),r.id());return dto(owned(actor.userId(),id,false));}
 public Attempt submit(SessionPrincipal actor,String id,SubmitInput input){identities.current(actor);if(input==null||input.confirmWordRange()==null)throw BusinessException.invalid("confirmWordRange","请确认词数提醒");users.lockUser(actor.userId());var command=List.of(id,input);Long old=replay(actor.userId(),input.requestId(),"SUBMIT",command);if(old!=null)return dto(owned(actor.userId(),""+old,false));var r=owned(actor.userId(),id,true);version(r,input.expectedVersion());if(r.words()<1)throw BusinessException.invalid("answerText","请先填写英文作答");var c=contents.content(r.setVersion(),true);if(c.minWords()!=null&&(r.words()<c.minWords()||r.words()>c.maxWords())&&!input.confirmWordRange())throw new BusinessException(400,"PRACTICE_WORD_RANGE_CONFIRMATION_REQUIRED","作答超出建议词数，确认后仍可提交");jdbc.update("UPDATE practice_subjective_attempt SET status='COMPLETED',completed_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6),lock_version=lock_version+1 WHERE id=?",r.id());remember(actor.userId(),input.requestId(),"SUBMIT",command,r.id());return dto(owned(actor.userId(),id,false));}
 public Attempt revise(SessionPrincipal actor,String id,PracticeDtos.RetryInput input){identities.current(actor);if(input==null)throw BusinessException.invalid("requestId","请提供修改命令");users.lockUser(actor.userId());var command=List.of(id,input);Long old=replay(actor.userId(),input.requestId(),"REVISE",command);if(old!=null)return dto(owned(actor.userId(),""+old,false));var r=owned(actor.userId(),id,true);if(!"COMPLETED".equals(r.status()))throw conflict();var active=active(actor.userId(),r.set());if(active!=null&&!Objects.equals(active.parent(),r.id()))throw new BusinessException(409,"PRACTICE_CONFLICT","此题目已有另一份未提交草稿，请先继续该草稿");long created=active==null?create(actor.userId(),r.set(),r.setVersion(),r.id(),r.text()):active.id();remember(actor.userId(),input.requestId(),"REVISE",command,created);return dto(owned(actor.userId(),""+created,false));}
 public ReadingDtos.PageDto<History> history(SessionPrincipal actor,PracticeDtos.Query q){identities.current(actor);var args=new ArrayList<Object>();args.add(actor.userId());String from=" FROM practice_subjective_attempt t JOIN practice_set s ON s.id=t.set_id JOIN practice_set_version v ON v.id=t.set_version_id WHERE t.user_id=?";
  var fields=new LinkedHashMap<String,Object>();fields.put("s.exam_code",q.exam());fields.put("v.reading_type",q.readingType());fields.put("JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.sourceKind'))",q.source());fields.put("JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.topic'))",q.topic());fields.put("JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.year'))",q.year());fields.put("JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.month'))",q.month());fields.put("JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.paperNo'))",q.paperNo());if(q.state()!=null&&!q.state().equals("ALL"))fields.put("t.status",q.state());if(q.section()!=null&&!q.section().equals("all"))fields.put("s.section",q.section().toUpperCase(Locale.ROOT));for(var f:fields.entrySet())if(f.getValue()!=null&&!f.getValue().toString().isBlank()){from+=" AND "+f.getKey()+"=?";args.add(f.getValue());}
  if(q.q()!=null&&!q.q().isBlank()){from+=" AND (LOCATE(?,JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.title')))>0 OR LOCATE(?,JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.titleZh')))>0)";args.add(q.q());args.add(q.q());}
  long total=jdbc.queryForObject("SELECT COUNT(*)"+from,Long.class,args.toArray());args.add(q.pageSize());args.add((q.page()-1)*q.pageSize());var values=jdbc.query("SELECT t.*,v.reading_type,v.metadata_json"+from+" ORDER BY t.started_at DESC,t.id DESC LIMIT ? OFFSET ?",(r,n)->{var m=json.readValue(r.getString("metadata_json"),PracticeDtos.Metadata.class);return new History(r.getString("id"),r.getString("set_id"),m.titleZh().isBlank()?m.title():m.titleZh(),r.getString("reading_type"),r.getString("status"),r.getInt("word_count"),r.getTimestamp("started_at").toInstant(),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toInstant());},args.toArray());return new ReadingDtos.PageDto<>(values,q.page(),q.pageSize(),total);}
}
